import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
C='REACH'
E(C,'M1-Z01','I ruoli nel REACH',[CL("Qual è il ruolo nel REACH?","Seleziona un’impresa, poi il suo ruolo.",["Fabbricante","Importatore","Utilizzatore a valle","Distributore","Produttore di articoli"],[
 ["Produce nell’Unione un solvente per la vendita",0,"Fabbrica la sostanza nell’Unione."],["Acquista una resina dalla Cina e la porta in Italia",1,"Introduce la sostanza nel territorio doganale dell’Unione."],
 ["Usa una vernice acquistata in Italia per verniciare mobili",2,"Usa una miscela nell’esercizio dell’attività."],["Rivende detergenti senza modificarli",3,"Immagazzina e immette sul mercato senza usare."],
 ["Fabbrica cavi elettrici con un rivestimento in PVC",4,"Produce articoli."],["Formula una colla miscelando sostanze acquistate in Italia",2,"Il formulatore è un utilizzatore a valle."],
 ["Importa smartphone completi",1,"Importa articoli: per gli articoli valgono gli obblighi dell’art. 7 e 33."],["Usa un lubrificante per le proprie macchine",2,"È utilizzatore a valle."]],
 "Otto imprese. Individua il ruolo di ciascuna nel regolamento REACH: da questo dipendono gli obblighi.","Reg. (CE) 1907/2006, art. 3")])
E(C,'M1-Z02','La registrazione',[LB("Laboratorio · Serve registrare?","Un’impresa italiana importa da fuori Unione le seguenti merci ogni anno.",[
  ["Sostanza A","0,6 t come tale"],["Sostanza B","15 t come tale, classificata pericolosa"],["Miscela M","20 t di una miscela che contiene il 40% della sostanza C"],["Rappresentante esclusivo","nessuno"]],[
  ("Calcola le tonnellate annue per sostanza.",5,"A: 0,6 t. B: 15 t. C: 20 × 0,40 = 8 t, perché per le miscele si conta la quantità di ciascuna sostanza contenuta.",["Ho calcolato 8 t per la sostanza C","Ho considerato le sostanze in miscela"]),
  ("Quali sostanze vanno registrate e con quali requisiti?",7,"A: sotto 1 t, nessuna registrazione. B: registrazione nella fascia 10-100 t con relazione sulla sicurezza chimica e, essendo pericolosa, scenari di esposizione. C: registrazione nella fascia 1-10 t. Le registrazioni si fanno tramite il SIEF della sostanza, con condivisione dei dati.",["Ho escluso A","Ho indicato la relazione per B","Ho indicato la fascia di C e il SIEF"]),
  ("Quale alternativa riduce gli oneri dell’importatore?",5,"Chiedere al fabbricante extra-UE di nominare un rappresentante esclusivo che registri le sostanze: l’importatore diventa utilizzatore a valle. In alternativa acquistare da un importatore che ha già registrato.",["Ho proposto il rappresentante esclusivo","Ho spiegato il cambio di ruolo"])],
 "Nel laboratorio verifichi gli obblighi di registrazione di un importatore. Calcola le tonnellate per sostanza, stabilisci che cosa registrare e individua un’alternativa che riduca gli oneri, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1907/2006, artt. 6, 8, 10 e 14")])
E(C,'M1-Z03','Il rappresentante esclusivo del fabbricante extra-UE',[SC("Il fornitore con il rappresentante esclusivo","Un fabbricante indiano dichiara di avere un rappresentante esclusivo nell’Unione che copre le importazioni della tua impresa per una sostanza.",[
 ("Che cosa verifichi?",[["Che il rappresentante abbia registrato la sostanza e che la tua impresa sia nel suo elenco di importatori coperti, con le quantità",True,"Corretto: senza copertura l’obbligo resta all’importatore."],["Solo la fattura",False,"Non dimostra la copertura."],["Nulla, basta la dichiarazione",False,"Va verificata."]]),
 ("Se sei coperto, che ruolo hai?",[["Utilizzatore a valle",True,"Corretto: gli importatori coperti sono considerati utilizzatori a valle."],["Importatore con obbligo di registrare",False,"La registrazione è del rappresentante."],["Distributore",False,"Non è il caso."]]),
 ("Le quantità importate crescono oltre la fascia registrata. Che cosa fai?",[["Lo comunichi al rappresentante perché aggiorni la registrazione",True,"Corretto: la registrazione deve coprire le quantità."],["Nulla",False,"La copertura potrebbe non bastare."],["Registri tu la differenza",False,"Si coordina con il rappresentante."]])],
 "Con un rappresentante esclusivo l’importatore diventa utilizzatore a valle, ma deve verificare registrazione, copertura e quantità.","Un fornitore extra-UE con rappresentante esclusivo. Verifica la tua posizione.","Reg. (CE) 1907/2006, art. 8")])
E(C,'M1-Z04','SVHC, elenco di sostanze candidate e articoli',[LB("Laboratorio · Lo 0,1% nell’articolo complesso","Un’impresa importa biciclette. Le manopole contengono un plastificante dell’elenco delle sostanze candidate.",[
  ["Bicicletta","15 kg"],["Manopole","2 manopole da 120 g ciascuna"],["SVHC","0,3 g in ciascuna manopola"],["Importazioni annue","10.000 biciclette"]],[
  ("Calcola la concentrazione e stabilisci se si applica l’art. 33.",6,"Ogni manopola è un articolo: 0,3 / 120 = 0,25%, oltre lo 0,1%. Si applica l’art. 33 anche se rispetto alla bicicletta intera la concentrazione sarebbe minima: la soglia si calcola su ogni articolo componente.",["Ho calcolato lo 0,25%","Ho applicato la soglia al componente","Ho concluso che l’art. 33 si applica"]),
  ("Serve la notifica all’ECHA dell’art. 7, comma 2?",6,"Quantità annua di SVHC: 10.000 biciclette × 2 manopole × 0,3 g = 6 kg, molto sotto 1 t: la notifica dell’art. 7, comma 2, non è dovuta. Resta la notifica alla banca dati SCIP.",["Ho calcolato 6 kg","Ho confrontato con 1 t","Ho ricordato la SCIP"]),
  ("Quali informazioni fornisci e a chi?",5,"Ai clienti professionali, alla fornitura, il nome della sostanza e le informazioni per l’uso sicuro; ai consumatori che lo chiedono, gratuitamente entro 45 giorni; la notifica SCIP all’ECHA prima dell’immissione sul mercato.",["Ho indicato i clienti professionali","Ho indicato i consumatori","Ho indicato la SCIP"])],
 "Nel laboratorio applichi la soglia dello zero virgola uno per cento a un articolo complesso, una bicicletta. Calcola la concentrazione, verifica la notifica e indica le informazioni da fornire, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1907/2006, artt. 7 e 33 · Corte di giustizia UE, C-106/14")])
E(C,'M1-Z05','Autorizzazione e restrizioni',[CL("Autorizzazione o restrizione?","Seleziona una caratteristica, poi lo strumento REACH.",["Autorizzazione (Allegato XIV)","Restrizione (Allegato XVII)"],[
 ["Dopo la data di scadenza la sostanza si usa solo per usi autorizzati",0,"È il meccanismo dell’autorizzazione."],["Limita il contenuto di nichel rilasciato dagli articoli a contatto con la pelle",1,"È una restrizione."],
 ["L’utilizzatore a valle notifica all’ECHA l’uso entro tre mesi dalla prima fornitura",0,"Art. 66."],["Vieta le microplastiche aggiunte intenzionalmente oltre una certa concentrazione",1,"Voce dell’Allegato XVII."],
 ["Riguarda sostanze estremamente preoccupanti prioritarie",0,"Le SVHC prioritarie passano all’Allegato XIV."],["Impone la formazione per l’uso professionale dei diisocianati",1,"Voce 74 dell’Allegato XVII."]],
 "Sei caratteristiche. Distingui quelle dell’autorizzazione da quelle delle restrizioni.","Reg. (CE) 1907/2006, Titoli VII e VIII")])
E(C,'M1-Z06','La restrizione sulle microplastiche aggiunte intenzionalmente',[SC("I glitter del negozio di bricolage","Un negozio di articoli per il fai da te vende glitter sfusi in plastica per decorazioni e chiede se può continuare.",[
 ("I glitter sfusi rientrano nella restrizione?",[["Sì: sono microplastiche aggiunte intenzionalmente immesse sul mercato come tali, vietate dal 17 ottobre 2023",True,"Corretto."],["No, sono un prodotto decorativo",False,"L’uso decorativo non li esclude."],["Solo se venduti online",False,"Il canale non conta."]]),
 ("Che cosa può vendere in alternativa?",[["Glitter non coperti dalla definizione, ad esempio solubili, biodegradabili secondo i criteri o di origine naturale non modificata chimicamente",True,"Corretto: occorre verificare la documentazione del fornitore."],["Gli stessi glitter in confezioni più piccole",False,"La restrizione resta."],["Qualsiasi glitter etichettato «eco»",False,"Un’etichetta non basta."]]),
 ("Come si tutela il negozio?",[["Chiedendo ai fornitori dichiarazioni e documentazione sulla conformità",True,"Corretto."],["Ignorando la restrizione",False,"Espone a sanzioni."],["Togliendo l’etichetta",False,"Non cambia la sostanza."]])],
 "Le microplastiche aggiunte intenzionalmente sono vietate come tali: chi vende prodotti alternativi deve averne la documentazione dal fornitore.","Un negozio vende glitter in plastica. Verifica la restrizione.","Reg. (UE) 2023/2055")])
E(C,'M1-Z07','Le sostanze dell’Allegato XIV: uso autorizzato e obblighi a valle',[SC("La cromatura con triossido di cromo","Un’impresa di cromatura decorativa acquista triossido di cromo da un fornitore titolare di un’autorizzazione per il suo uso.",[
 ("Può continuare a usarlo?",[["Sì, se il suo uso rientra in quello autorizzato e rispetta le condizioni dell’autorizzazione",True,"Corretto: gli utilizzatori a valle possono avvalersi dell’autorizzazione del fornitore."],["Sì, sempre",False,"Servono uso coperto e condizioni rispettate."],["No, mai",False,"È possibile se coperto."]]),
 ("Quale adempimento verso l’ECHA?",[["Notificare l’uso entro tre mesi dalla prima fornitura",True,"Corretto: art. 66."],["Nessuno",False,"La notifica è obbligatoria."],["Registrare la sostanza",False,"Non spetta all’utilizzatore a valle."]]),
 ("Quali condizioni sono tipiche in questi casi?",[["Misure di controllo dell’esposizione, monitoraggio dell’aria e biologico, e attenzione alle alternative",True,"Corretto."],["Solo l’etichetta",False,"Le condizioni sono più ampie."],["Nessuna",False,"L’autorizzazione ha condizioni."]])],
 "Uso coperto e condizioni rispettate, notifica entro tre mesi, monitoraggio e ricerca di alternative: sono gli obblighi a valle delle sostanze soggette ad autorizzazione.","Una cromatura usa una sostanza soggetta ad autorizzazione. Verifica gli obblighi.","Reg. (CE) 1907/2006, artt. 56 e 66")])
E(C,'M1-Z08','Autorizzazione e restrizioni',[LB("Laboratorio · Verificare le restrizioni su articoli","Un’impresa progetta e vende accessori di abbigliamento e oggetti in gomma per il pubblico.",[
  ["Prodotto 1","fibbie metalliche per cinture, a contatto prolungato con la pelle"],["Prodotto 2","impugnature in gomma per utensili da giardino"],["Prodotto 3","portachiavi per bambini in plastica morbida"],["Fornitori","extra-UE, senza dichiarazioni"]],[
  ("Individua le restrizioni da verificare per ogni prodotto.",7,"Fibbie: rilascio di nichel, voce 27, con limite di 0,5 µg/cm² per settimana per il contatto prolungato. Impugnature: idrocarburi policiclici aromatici, voce 50, limite di 1 mg/kg per ciascuno degli otto IPA nei componenti a contatto con la pelle per il pubblico. Portachiavi: ftalati, voce 51, e, se considerati giocattoli, limiti più severi; IPA a 0,5 mg/kg per i giocattoli.",["Ho indicato il nichel","Ho indicato gli IPA con i limiti","Ho considerato gli ftalati"],None,120),
  ("Come organizzi i controlli sui fornitori?",6,"Capitolato con le restrizioni applicabili; dichiarazioni di conformità; rapporti di prova di laboratori accreditati su campioni rappresentativi; controlli a campione sui lotti; azioni in caso di non conformità.",["Ho previsto capitolato e dichiarazioni","Ho previsto prove di laboratorio","Ho previsto controlli sui lotti"]),
  ("Che cosa fai se un lotto di fibbie supera il limite del nichel?",5,"Si blocca il lotto, non si immette sul mercato, si informa il fornitore, si valutano richiamo o ritiro se già venduto e si rafforzano i controlli; si documenta tutto.",["Ho bloccato il lotto","Ho considerato il ritiro","Ho previsto la documentazione"])],
 "Nel laboratorio verifichi le restrizioni dell’Allegato diciassette su tre articoli. Individua le restrizioni applicabili, organizza i controlli sui fornitori e decidi come gestire una non conformità, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1907/2006, Allegato XVII, voci 27, 50 e 51")])
E(C,'M1-Z09','Esercitazione · L’importazione diretta',[LB("Laboratorio · La mappa REACH della tua impresa","Prepari la mappa REACH di un’impresa che produce adesivi.",[
  ["Acquisti","12 sostanze da fornitori italiani; 2 sostanze importate dalla Corea, 4 e 25 t l’anno"],["Prodotti","adesivi per l’industria e per il fai da te"],["Contenuti","un adesivo contiene diisocianati allo 0,5%"]],[
  ("Indica i ruoli dell’impresa e gli obblighi principali.",7,"Utilizzatore a valle e formulatore per le sostanze acquistate in Italia: verificare gli usi negli scenari, preparare SDS e scenari per i clienti. Importatore per le due sostanze coreane: registrazione nelle fasce 1-10 e 100-1000 t, salvo rappresentante esclusivo. Fornitore di miscele: classificazione, etichettatura, notifica ai centri antiveleni e UFI.",["Ho indicato i ruoli","Ho indicato la registrazione","Ho indicato gli obblighi del formulatore"]),
  ("Quali obblighi speciali derivano dall’adesivo con diisocianati?",5,"Restrizione della voce 74: etichetta con l’avviso sulla formazione per gli usi professionali e industriali; per il fai da te verificare le condizioni di vendita al pubblico previste dalle norme; formazione degli utilizzatori professionali.",["Ho richiamato la voce 74","Ho distinto professionale e pubblico"]),
  ("Quali sono le priorità dei prossimi sei mesi?",5,"Verificare le registrazioni delle importazioni o nominare il rappresentante esclusivo; controllare SDS e scenari in entrata e in uscita; aggiornare etichette e notifiche; monitorare l’elenco delle candidate per le sostanze usate.",["Ho previsto le registrazioni","Ho previsto SDS ed etichette","Ho previsto il monitoraggio delle SVHC"])],
 "Nel laboratorio prepari la mappa REACH di un’impresa che produce adesivi. Individua ruoli e obblighi, gli obblighi legati ai diisocianati e le priorità dei prossimi sei mesi, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1907/2006 · Reg. (CE) 1272/2008"),
 AP("Il REACH nella tua impresa","Verifica la tua posizione rispetto al REACH.",["Conosco il mio ruolo per ogni prodotto","Importo sostanze o miscele da fuori Unione","Ricevo SDS estese con scenari","Verifico gli usi negli scenari","Fornisco articoli con SVHC","Controllo le restrizioni sui prodotti"],"L’obbligo REACH più urgente per te","Es.: verificare la registrazione della resina importata",
  "Verifica la posizione della tua impresa rispetto al REACH e indica l’obbligo più urgente.",3),
 VF("Ripasso · REACH",[["La registrazione è obbligatoria da 1 t/anno per fabbricante o importatore.",True,"Vero."],["La soglia dello 0,1% per le SVHC si calcola sull’articolo complesso intero.",False,"Falso: si calcola su ogni articolo componente."],["L’importatore coperto da un rappresentante esclusivo è un utilizzatore a valle.",True,"Vero."],["Le restrizioni dell’Allegato XVII riguardano solo le sostanze, non gli articoli.",False,"Falso: molte restrizioni riguardano articoli."]],"Ripasso: quattro affermazioni sul REACH.","Reg. (CE) 1907/2006")])
# ── M2 ──
E(C,'M2-Z01','Verificare la qualità di una SDS',[LB("Laboratorio · Coerenza tra sezioni della SDS","Controlli la coerenza interna della scheda di un detergente industriale.",[
  ["Sezione 2","classificazione: Eye Irrit. 2 (H319)"],["Sezione 3","12% di un componente classificato Eye Dam. 1 (H318); 5% di un tensioattivo Skin Irrit. 2"],["Sezione 9","punto di infiammabilità: 45 °C"],["Sezione 14","non soggetto ad ADR"]],[
  ("La classificazione per gli occhi è coerente con la composizione?",6,"No. Con il metodo di calcolo una miscela con almeno il 3% di componenti Eye Dam. 1 è classificata Eye Dam. 1, H318, salvo dati specifici. Con il 12% la classificazione corretta è Eye Dam. 1.",["Ho applicato la soglia del 3%","Ho concluso Eye Dam. 1"]),
  ("Che cosa noti sul punto di infiammabilità?",6,"Un punto di infiammabilità di 45 °C rientra nei liquidi infiammabili di categoria 3, tra 23 e 60 °C: manca la classificazione H226, salvo deroghe per liquidi che non sostengono la combustione da dimostrare. Va verificata anche la coerenza con la sezione 14.",["Ho collegato 45 °C alla categoria 3","Ho rilevato H226 mancante","Ho considerato la sezione 14"]),
  ("Come procedi con il fornitore e internamente?",5,"Si segnalano per iscritto le incoerenze e si chiede una SDS corretta; nel frattempo si gestisce il prodotto secondo la classificazione più severa, con protezione degli occhi e misure contro l’incendio, e si aggiorna la valutazione dei rischi.",["Ho chiesto la correzione","Ho adottato la classificazione più severa","Ho aggiornato la valutazione"])],
 "Nel laboratorio controlli la coerenza tra le sezioni della scheda di un detergente. Verifica la classificazione per gli occhi, il punto di infiammabilità e decidi come procedere, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1272/2008, Allegato I · Reg. (UE) 2020/878")])
E(C,'M2-Z02','Il regolamento CLP: classi e categorie di pericolo',[ES("Esempio guidato · Quale categoria di liquido infiammabile?","I criteri del punto di infiammabilità e del punto di ebollizione.",[
 ["Categoria 1","Punto di infiammabilità sotto 23 °C e punto iniziale di ebollizione fino a 35 °C.","H224"],
 ["Categoria 2","Punto di infiammabilità sotto 23 °C e punto iniziale di ebollizione oltre 35 °C.","H225"],
 ["Categoria 3","Punto di infiammabilità tra 23 e 60 °C.","H226"],
 ["Il caso","Un diluente ha punto di infiammabilità di 12 °C e punto di ebollizione di 110 °C.","Categoria 2 · H225"],
 ["L’etichetta","Pittogramma GHS02, avvertenza «Pericolo».","GHS02 · Pericolo"]],
 "Classifichiamo un liquido infiammabile. Sotto i ventitré gradi di punto di infiammabilità si è in categoria uno o due, a seconda che il punto di ebollizione sia fino a trentacinque gradi o superiore; tra ventitré e sessanta gradi si è in categoria tre. Un diluente con infiammabilità a dodici gradi ed ebollizione a centodieci è in categoria due, con H duecentoventicinque, fiamma e avvertenza «Pericolo».","Reg. (CE) 1272/2008, Allegato I, punto 2.6")])
E(C,'M2-Z03','Il codice UFI e la notifica ai centri antiveleni',[LB("Laboratorio · La notifica ai centri antiveleni","Un formulatore immette sul mercato italiano un nuovo detergente classificato Skin Corr. 1.",[
  ["Uso","professionale"],["Composizione","4 componenti, uno con identità riservata dal fornitore"],["Mercati","Italia, poi Francia"],["Etichetta","in preparazione"]],[
  ("Chi notifica, quando e con quali informazioni?",6,"Il formulatore, come utilizzatore a valle che immette la miscela sul mercato, prima dell’immissione, tramite il portale ECHA nel formato armonizzato: identificazione, classificazione ed etichetta, composizione con concentrazioni, informazioni tossicologiche, categoria di prodotto EuPCS e UFI.",["Ho indicato chi e quando","Ho indicato il portale e il formato","Ho elencato le informazioni"]),
  ("Come gestisci il componente con identità riservata?",5,"Si chiede al fornitore di comunicare le informazioni direttamente all’ECHA o di fornire il suo UFI di miscela in miscela, così che la notifica sia completa senza rivelare l’identità al formulatore.",["Ho proposto la comunicazione del fornitore","Ho citato l’UFI della miscela in miscela"]),
  ("Che cosa cambia per l’etichetta e per la Francia?",6,"Il codice UFI di 16 caratteri va riportato sull’etichetta, in genere vicino alle informazioni supplementari; per la Francia serve la notifica anche per quello Stato membro e l’etichetta in lingua francese. Ogni modifica significativa della composizione richiede l’aggiornamento della notifica e, se necessario, un nuovo UFI.",["Ho indicato l’UFI in etichetta","Ho considerato lingua e Stato membro","Ho previsto gli aggiornamenti"])],
 "Nel laboratorio prepari la notifica ai centri antiveleni di un nuovo detergente. Indica chi notifica e con quali informazioni, come gestire un componente riservato e che cosa cambia per etichetta e mercati esteri, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1272/2008, art. 45 e Allegato VIII")])
E(C,'M2-Z04','Controlli e sanzioni in Italia',[SC("L’ispezione sulle schede di sicurezza","Durante un controllo sul REACH e sul CLP, gli ispettori chiedono a un distributore di prodotti chimici le SDS di dieci prodotti e le prove della loro trasmissione ai clienti.",[
 ("Che cosa mostri?",[["Le SDS aggiornate in italiano e le evidenze dell’invio ai clienti alla prima fornitura e dopo ogni revisione",True,"Corretto: il distributore deve trasmettere le SDS lungo la catena."],["Solo le fatture",False,"Non dimostrano l’invio delle SDS."],["Le SDS del fornitore in inglese",False,"Vanno in italiano."]]),
 ("Una SDS è del 2018 e il fornitore ha emesso una revisione nel 2024 che non hai trasmesso. Che cosa rischi?",[["Una sanzione per la mancata trasmissione delle informazioni aggiornate",True,"Corretto: le violazioni sono sanzionate dal D.lgs. 133/2009."],["Nulla, la vecchia scheda va bene",False,"La revisione va trasmessa."],["Solo un richiamo verbale",False,"Sono previste sanzioni."]]),
 ("Come eviti il problema in futuro?",[["Un sistema che registra versioni e invii delle SDS e avvisa i clienti a ogni revisione",True,"Corretto."],["Inviare le SDS solo su richiesta",False,"L’obbligo è automatico."],["Pubblicarle sul sito e basta",False,"Va dimostrato l’invio ai clienti."]])],
 "SDS aggiornate, in italiano, trasmesse ai clienti a ogni revisione e con prova dell’invio: è ciò che gli ispettori verificano presso i distributori.","Un controllo sulle schede di sicurezza presso un distributore. Prepara le evidenze.","Art. 31 Reg. (CE) 1907/2006 · D.lgs. 133/2009")])
E(C,'M2-Z05','Le novità dell’Allegato II: Regolamento (UE) 2020/878',[CL("In quale sezione della SDS?","Seleziona un’informazione, poi la sezione della scheda.",["Sezione 2","Sezione 3","Sezione 7","Sezione 8","Sezione 9","Sezione 14"],[
 ["Pittogrammi e indicazioni di pericolo",0,"Identificazione dei pericoli."],["Concentrazioni dei componenti e fattori M",1,"Composizione."],
 ["Incompatibilità di stoccaggio",2,"Manipolazione e immagazzinamento."],["Tipo di guanto e di filtro respiratorio",3,"Controllo dell’esposizione e protezione individuale."],
 ["Punto di infiammabilità",4,"Proprietà fisiche e chimiche."],["Numero ONU e classe ADR",5,"Informazioni sul trasporto."],
 ["Valori limite di esposizione professionale",3,"Sezione 8."],["Stime della tossicità acuta dei componenti",1,"Con il Reg. (UE) 2020/878 vanno in sezione 3."]],
 "Otto informazioni della scheda di dati di sicurezza. Indica in quale sezione si trovano.","Reg. (UE) 2020/878")])
E(C,'M2-Z06','Esercitazione · L’etichetta in inglese',[LB("Laboratorio · L’etichetta di una nuova miscela","Prepari l’etichetta di una miscela sgrassante da vendere a utilizzatori professionali.",[
  ["Componente X","20%, stima della tossicità acuta orale 500 mg/kg"],["Altri componenti","non classificati per la tossicità acuta"],["Classificazione già determinata","liquido infiammabile categoria 3; irritazione cutanea categoria 2"],["Confezione","5 litri"]],[
  ("La miscela è classificata per tossicità acuta orale? Calcola l’ATEmix.",6,"ATEmix = 100 / (20 / 500) = 2.500 mg/kg. È oltre 2.000 mg/kg, quindi la miscela non è classificata per tossicità acuta orale.",["Ho applicato la formula","Ho ottenuto 2.500 mg/kg","Ho confrontato con 2.000"]),
  ("Elenca gli elementi dell’etichetta.",7,"Identificatore del prodotto e UFI; nome, indirizzo e telefono del fornitore; quantità nominale; pittogrammi GHS02 e GHS07; avvertenza «Attenzione»; H226 e H315; consigli di prudenza pertinenti, ad esempio P210, P280, P302+P352; in lingua italiana.",["Ho indicato i pittogrammi corretti","Ho indicato l’avvertenza «Attenzione»","Ho indicato frasi H e P in italiano"]),
  ("Quali errori eviti?",5,"Etichetta solo in inglese; avvertenza «Pericolo» non coerente con le categorie; pittogrammi ridondanti; mancanza dell’UFI; dimensioni non leggibili; informazioni non coerenti con la SDS.",["Ho indicato la lingua","Ho indicato la coerenza con la SDS","Ho indicato UFI e leggibilità"])],
 "Nel laboratorio prepari l’etichetta di una nuova miscela sgrassante. Calcola la stima della tossicità acuta, elenca gli elementi dell’etichetta e gli errori da evitare, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1272/2008, artt. 17 e 18 e Allegato I"),
 AP("Le etichette e le schede della tua impresa","Verifica la gestione di etichette e schede di sicurezza.",["Tutti i prodotti hanno SDS in italiano","Le SDS sono aggiornate","Le etichette sono coerenti con le SDS","Le miscele immesse sul mercato sono notificate","L’UFI è in etichetta","Esiste un sistema di invio delle SDS ai clienti"],"Il controllo che farai per primo","Es.: confronto tra sezione 2 e sezione 3 delle dieci SDS più usate",
  "Verifica come la tua impresa gestisce etichette e schede di sicurezza e indica il primo controllo che farai.",3)])

E(C,'M1-Z10','Il regolamento REACH e gli obblighi dell’utilizzatore',[SC("L’uso che lo scenario non prevede","Un’impresa riceve la SDS estesa di una sostanza registrata: il suo uso, la nebulizzazione per la pulizia di stampi, non compare tra gli usi identificati.",[
 ("Entro quando deve agire?",[["Entro 12 mesi dalla ricezione della SDS estesa",True,"Corretto: è il termine per adeguarsi o scegliere un’altra strada."],["Entro 5 anni",False,"Il termine è molto più breve."],["Non deve fare nulla",False,"L’uso non coperto va gestito."]]),
 ("Quali opzioni ha?",[["Adeguare l’uso, chiedere al fornitore di includerlo o preparare una propria relazione sulla sicurezza chimica",True,"Corretto: sono le opzioni dell’art. 37."],["Solo cambiare fornitore",False,"È possibile ma non è l’unica opzione."],["Continuare senza modifiche",False,"Non è conforme."]]),
 ("Che cosa comunica all’ECHA se prepara la propria relazione?",[["Le informazioni previste dall’art. 38, salvo esenzioni come quantità inferiori a 1 t/anno",True,"Corretto."],["Nulla",False,"Ci sono obblighi di comunicazione."],["Solo il nome dell’impresa",False,"Non basta."]])],
 "Un uso non coperto dallo scenario si gestisce entro dodici mesi: adeguandosi, chiedendo al fornitore di includerlo o con una propria valutazione comunicata all’ECHA.","Un uso non previsto nella SDS estesa. Decidi come procedere.","Reg. (CE) 1907/2006, artt. 37 e 38")])
E(C,'M2-Z07','Il regolamento CLP: classi e categorie di pericolo',[LB("Laboratorio · Classificare una miscela per l’ambiente","Classifichi per i pericoli per l’ambiente acquatico una miscela antivegetativa.",[
  ["Componente P","2%, Aquatic Chronic 1, fattore M = 1"],["Componente Q","4%, Aquatic Chronic 2"],["Altri componenti","non classificati per l’ambiente"],["Regole di somma","Chronic 1 se Σ(C1 × M) ≥ 25%; Chronic 2 se Σ(C1 × M × 10) + Σ C2 ≥ 25%; Chronic 3 se Σ(C1 × M × 100) + Σ(C2 × 10) + Σ C3 ≥ 25%"]],[
  ("Applica il metodo della somma con M = 1.",7,"Chronic 1: 2 × 1 = 2%, sotto 25%. Chronic 2: 2 × 1 × 10 + 4 = 24%, sotto 25%. Chronic 3: 2 × 1 × 100 + 4 × 10 = 240%, oltre 25%. La miscela è Aquatic Chronic 3, H412, senza pittogramma.",["Ho applicato le tre somme in ordine","Ho ottenuto Chronic 3","Ho indicato H412 senza pittogramma"]),
  ("Che cosa cambia se il fattore M del componente P è 10?",6,"Chronic 1: 2 × 10 = 20%, sotto 25%. Chronic 2: 2 × 10 × 10 + 4 = 204%, oltre 25%. La miscela è Aquatic Chronic 2, H411, con pittogramma GHS09.",["Ho ricalcolato con M = 10","Ho ottenuto Chronic 2","Ho indicato il pittogramma GHS09"]),
  ("Dove si trova il fattore M e perché è importante?",5,"In sezione 3 della SDS del fornitore, come previsto dal Reg. (UE) 2020/878, oppure nella classificazione armonizzata. Moltiplica il peso dei componenti molto tossici: ignorarlo porta a sottovalutare la classificazione.",["Ho indicato la sezione 3","Ho spiegato l’effetto del fattore M"])],
 "Nel laboratorio classifichi una miscela per i pericoli per l’ambiente acquatico con il metodo della somma. Applica le regole con due diversi fattori M e spiega il ruolo del fattore, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (CE) 1272/2008, Allegato I, punto 4.1.3.5")])
E(C,'M2-Z08','L’etichetta CLP e le novità della revisione',[SC("Il prodotto venduto online","Un’impresa vende online un disincrostante classificato Skin Corr. 1. La pagina del prodotto mostra solo foto, prezzo e descrizione commerciale.",[
 ("La pagina è conforme?",[["No: chi vende a distanza deve indicare i pericoli prima dell’acquisto, come pittogrammi, avvertenza e indicazioni di pericolo",True,"Corretto: il CLP richiede le informazioni sui pericoli anche nella pubblicità e nelle vendite a distanza."],["Sì, l’etichetta è sulla confezione",False,"Il consumatore deve conoscere i pericoli prima di acquistare."],["Sì, se c’è il link alla SDS",False,"Non basta."]]),
 ("Che cosa aggiungi alla pagina?",[["Pittogramma, avvertenza, indicazioni di pericolo e, se previsto, informazioni supplementari, coerenti con l’etichetta",True,"Corretto."],["Una frase «maneggiare con cura»",False,"È generica."],["Nulla",False,"Le informazioni sono obbligatorie."]]),
 ("Chi controlla la coerenza tra pagina, etichetta e SDS?",[["Un responsabile interno con una procedura di revisione a ogni aggiornamento",True,"Corretto."],["Il fornitore del sito web",False,"La responsabilità è dell’impresa."],["Nessuno",False,"Serve un controllo."]])],
 "Nella vendita a distanza i pericoli vanno mostrati prima dell’acquisto, coerenti con etichetta e SDS e aggiornati a ogni revisione.","Un prodotto pericoloso venduto online. Verifica la pagina.","Reg. (CE) 1272/2008, art. 48, come modificato dal Reg. (UE) 2024/2865")])
